type ClientContext = Readonly<Record<string, string | number | boolean | null>> & {
    readonly user_id: string | number | null;
};

type ClientDefaults = {
    now?: () => Date;
    id?: (kind: 'uuid' | 'ulid', model: ModelContract) => string;
};

type CreateInput<D extends ContractMap, N extends keyof D> = {
    [F in Exclude<Writable<D, N>, OptionalCreate<D, N>>]: FieldValue<D, N, F>;
} & { [F in OptionalCreate<D, N>]?: FieldValue<D, N, F> } & {
    id?: string;
};

type DomainInput<D extends DomainContracts[string]> = {
    readonly [K in keyof D as D[K]['optional'] extends true ? never : K]: Value<D[K]>;
} & { readonly [K in keyof D as D[K]['optional'] extends true ? K : never]?: Value<D[K]> };

type DomainOptimistic<S extends Schema, D extends DomainContracts> = {
    readonly [N in keyof D]?: (options: {
        readonly tx: Transaction<S>;
        readonly args: DomainInput<D[N]>;
        readonly ctx: ClientContext;
    }) => Promise<void>;
};

type Filter<D extends ContractMap, N extends keyof D, F extends FilterName<D, N> = FilterName<D, N>> = F extends FilterName<D, N>
        ? {
              readonly model: N;
              readonly name: F;
              readonly value: FilterValue<D, N, F> | undefined;
          }
        : never;

type IncludeArgs = {
    include?: { [key: string]: IncludeArgs };
    order?: [string, 'asc' | 'desc'][];
    limit?: number;
};

type Model<S extends Schema, D extends ContractMap, N extends keyof D & string> = {
    readonly name: N;
    readonly definitions: D;
    readonly contract: D[N];
    readonly query: ModelQueries<S, D, N> & (() => ModelQueries<S, D, N>);
} & { [O in D[N]['mutations'][number]]: () => Mutation<S, D, N, O> };

readonly authorization: readonly {
        readonly field: string;
        readonly op: string;
        readonly value: { readonly context: string } | { readonly literal: string | number | boolean | null };
    }[];

readonly nestedMutations?: Partial<
        Readonly<Record<'create' | 'update', Readonly<Record<string, readonly ('create' | 'update')[]>>>>
    >;

readonly search?: {
        readonly index: string;
        readonly key: string;
        readonly queryBy: string;
        readonly fields: Readonly<Record<string, string>>;
        readonly facets: readonly string[];
        readonly sorts: readonly string[];
    };

readonly timestamps: {
        readonly created: string | null;
        readonly updated: string | null;
        readonly deleted: string | null;
    };

type ModelInstance<S extends Schema, D extends ContractMap, N extends keyof D & string, Row = ModelRow<D, N>> = ModelSnapshot<Data<S, D, N, Row>> & {
    readonly [O in Exclude<D[N]['mutations'][number], 'create'>]: () => Mutation<S, D, N, O, true>;
} & {
    readonly [R in 'one' extends D[N]['queries'][number] ? IncludeName<D, N> : never]: RelationSelection<S, D, N, R>;
};

type ModelRow<D extends ContractMap, N extends keyof D> = {
    readonly [F in keyof D[N]['columns']]: FieldValue<D, N, F>;
};

