type MutationArgs<ID extends string | number = string | number> = {
    id: ID;
    data: { [key: string]: ReadonlyJSONValue };
    now: number;
    relations?: { [name: string]: { operation: 'create' | 'update'; records: MutationArgs[] } };
};

type MutationFields<D extends ContractMap, N extends keyof D, Input> = {
    readonly [
        P in FieldPaths<Input> as [FieldComponent<D, N, P, Input>] extends [never] ? never : P
    ]: FieldDefinition & { readonly name: P; readonly component: FieldComponent<D, N, P, Input> };
};

type MutationForm<Values extends object, Result> = Omit<
    FormDescriptor<Values, Readonly<Record<string, FieldDefinition>>, Record<string, never>>,
    'submission'
> & {
    readonly submission: {
        submit(
            this: void,
            values: Values,
            context: { readonly signal: AbortSignal },
        ): Promise<MutationSubmissionResult<Result>>;
    };
};

type MutationSubmissionResult<Result> = | Exclude<SubmissionResult, { status: 'success' }>
    | {
          readonly status: 'success';
          readonly value:
              | { readonly resolved: true; readonly data: Result }
              | { readonly resolved: false; readonly error: MutationResultError };
      };

type NativeMutators<S extends Schema, D extends ContractMap> = AnyMutatorRegistry & {
    [N in keyof D]: {
        [O in D[N]['mutations'][number]]: Mutator<MutationArgs<RecordId<D, N>>, S, ClientContext>;
    };
};

type NativeQueries<S extends Schema, D extends ContractMap> = {
    [N in keyof D]: {
        [O in D[N]['queries'][number]]: CustomQuery<
            Table<S>,
            QueryArgs,
            QueryArgs,
            S,
            RawRow | undefined,
            ClientContext
        >;
    };
};

type PlainData<T> = T extends ModelSnapshot<infer Row>
        ? { readonly [K in keyof Row]: PlainData<Row[K]> }
        : T extends readonly (infer Item)[]
          ? readonly PlainData<Item>[]
          : ReadonlyValue<T>;

