};

type MutationCallback<S extends Schema, D extends ContractMap, N extends keyof D & string, O extends Operation, Bound extends boolean = false, Input = OperationInput<D, N, O, Bound>> = ((input: Input) => MutationCall<RecordId<D, N>>) & {
    readonly state: MutationState;
    readonly form: Mutation<S, D, N, O, Bound, Input>['form'] &
        MutationForm<Input> &
        FormDescriptor<
            MutationDraft<Input> & object,
            Mutation<S, D, N, O, Bound, Input>['form']['definition']['fields'],
            Record<string, never>
        > & {
            readonly submission: CallbackSubmission<MutationDraft<Input> & object>;
        };
    readonly defaultValues: Partial<Input>;
    submit(event?: { preventDefault(): void }): MutationCall<RecordId<D, N>>;
    reset(): void;
};

type MutationState = {
    status: 'idle' | 'pending' | 'success' | 'failure';
    phase: 'client' | 'server' | undefined;
    error: Error | undefined;
    fields: Readonly<Record<string, readonly string[]>>;
};

type ProviderProps = {
    userID: string | null;
    context: ClientContext;
    auth?: string | null | undefined;
    children: ReactNode;
};

type RenderHandlers<T, R> = {
    onIdle: () => R;
    onLoading: () => R;
    onRefreshing: (data: T) => R;
    onFailure: (error: Error) => R;
    onStale: (value: readonly [T, Error]) => R;
    onSuccess: (data: T) => R;
};

